async function api(url:string,method='GET',body?:any):Promise<any>{const r=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const j:any=await r.json();if(!r.ok)throw new Error(j.error??'Unable to complete this request.');return j}
